import ast
import json
from fractions import Fraction

expressions = {
    "A": """not (not (not not not (not (The capital of Canada is Ottawa.) or (max(3, 4, -2, 7) - min(3, 4, -2, 7) <= 2)) and not not (not not (False) or not not not (-2 - (10 / 8) is less than or equal to -3))) or (not ((4 * -8 + -6 * -9 is less than or equal to -5 * 5) or (max(1, 8, 1, 8) - min(1, 8, 1, 8) is greater than 1)) or (not not not (-7 * 1 + -2 * 7 is less than or equal to -5 * 7) and not not (2 * 3 + -1 * -10 is less than or equal to -4 * 5)))) and (not not (not not not (not not not (True) and not not (max(1, -5, -2, 1) - min(1, -5, -2, 1) > 6)) and not not (not not not (8 * 3 + -5 * -3 is greater than 7 * 4) and not not (10 * 10 <= 2))) or not not not (not (not not not (max(-2, 3, -9, 10) - min(-2, 3, -9, 10) <= 4) and not not (The capital of Afghanistan is Kabul.)) or (not not (2 * 4 + -5 * -8 is greater than 3 * 4) or not not not (-1 * -4 <= 2))))""",
    "C": """not not not (not not (not not ((not (not (not (not not (not (False) and (False)) or not not not (The capital of Malaysia is Kuala Lumpur.)) or (6 * -6 is less than or equal to 3)) or (max(2, -7, 1, -3) - min(2, -7, 1, -3) is greater than 7)) or (-3 * -8 <= 9)) and (False)) or not not not (True)) or not not not (-3 * 7 is less than or equal to -10)) and not not (9 - (5 / -9) is greater than -5)"""
}

facts = {
    "The capital of Canada is Ottawa.": True,
    "The capital of Afghanistan is Kabul.": True,
    "The capital of Malaysia is Kuala Lumpur.": True,
    "The capital of Armenia is Gyumri.": False,
}


def normalize(text):
    text = text.replace("is less than or equal to", "<=")
    text = text.replace("is greater than", ">")
    for statement, value in facts.items():
        text = text.replace(statement, str(value))
    return text


def evaluate(node):
    if isinstance(node, ast.Expression):
        return evaluate(node.body)
    if isinstance(node, ast.Constant):
        if isinstance(node.value, bool):
            return node.value
        if isinstance(node.value, int):
            return Fraction(node.value)
        raise ValueError("Unsupported constant")
    if isinstance(node, ast.UnaryOp):
        value = evaluate(node.operand)
        if isinstance(node.op, ast.Not):
            return not value
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return value
    if isinstance(node, ast.BoolOp):
        values = [bool(evaluate(x)) for x in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
    if isinstance(node, ast.BinOp):
        left, right = evaluate(node.left), evaluate(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return left / right
    if isinstance(node, ast.Compare):
        left = evaluate(node.left)
        results = []
        for operation, operand in zip(node.ops, node.comparators):
            right = evaluate(operand)
            if isinstance(operation, ast.LtE):
                result = left <= right
            elif isinstance(operation, ast.Gt):
                result = left > right
            else:
                raise ValueError("Unsupported comparison")
            results.append(result)
            left = right
        return all(results)
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
        values = [evaluate(x) for x in node.args]
        if node.func.id == "max":
            return max(values)
        if node.func.id == "min":
            return min(values)
    raise ValueError("Unsupported syntax")


def compute(text):
    return evaluate(ast.parse(normalize(text), mode="eval"))


try:
    values = {label: bool(compute(text))
              for label, text in expressions.items()}

    # These are explicit conjuncts in the original options. A false
    # conjunct settles the whole option, independently of its other terms.
    gates = {
        "B": "The capital of Armenia is Gyumri.",
        "D": "5 - (9 / 2) <= -10",
        "E": "5 * -7 + 4 * 2 > -8 * -3",
    }
    gate_values = {label: bool(compute(text))
                   for label, text in gates.items()}
    if any(gate_values.values()):
        print("UNSUPPORTED")
    else:
        values.update(gate_values)
        winners = [label for label in "ABCDE" if values[label]]
        if len(winners) != 1:
            print("UNSUPPORTED")
        else:
            evidence = {
                "values": {label: values[label] for label in "ABCDE"},
                "false_conjuncts": {
                    "B": "Armenia's capital is Yerevan, not Gyumri",
                    "D": "1/2 <= -10 is false",
                    "E": "-27 > 24 is false",
                },
                "arithmetic": "Exact rational evaluation",
            }
            print(json.dumps({
                "final_answer": winners[0],
                "evidence": evidence,
            }, separators=(",", ":")))
except Exception:
    print("UNSUPPORTED")
